import{_ as s,o as e,c as o,a as l}from"./app.DkoUFz-u.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"backend/observability/profiling/cpu.md","filePath":"backend/observability/profiling/cpu.md"}'),n={name:"backend/observability/profiling/cpu.md"};function a(i,t,r,c,d,p){return e(),o("div",null,[...t[0]||(t[0]=[l(`<p>好的，这是一份关于 CPU 性能分析的详细学习笔记。内容从基础概念到高级工具和实战流程，并辅以 Mermaid 图表进行梳理，力求完整和实用。</p><hr><h2 id="可观测性与性能分析-cpu-分析深度指南" tabindex="-1">可观测性与性能分析：CPU 分析深度指南 <a class="header-anchor" href="#可观测性与性能分析-cpu-分析深度指南" aria-label="Permalink to &quot;可观测性与性能分析：CPU 分析深度指南&quot;">​</a></h2><h3 id="_1-核心概念" tabindex="-1">1. 核心概念 <a class="header-anchor" href="#_1-核心概念" aria-label="Permalink to &quot;1. 核心概念&quot;">​</a></h3><h4 id="_1-1-什么是可观测性" tabindex="-1">1.1 什么是可观测性？ <a class="header-anchor" href="#_1-1-什么是可观测性" aria-label="Permalink to &quot;1.1 什么是可观测性？&quot;">​</a></h4><p>可观测性不仅仅是监控。它是指通过系统外部输出（如指标、日志、链路），来<strong>理解</strong>系统内部状态并<strong>探究</strong>未知问题的能力。</p><ul><li><strong>监控</strong>：基于已知故障模式，设置告警。（已知的未知）</li><li><strong>可观测性</strong>：当出现未知问题时，有能力提出新问题并找到根源。（未知的未知）</li></ul><h4 id="_1-2-cpu-相关的基础指标" tabindex="-1">1.2 CPU 相关的基础指标 <a class="header-anchor" href="#_1-2-cpu-相关的基础指标" aria-label="Permalink to &quot;1.2 CPU 相关的基础指标&quot;">​</a></h4><ul><li><strong>利用率</strong>：CPU 忙于执行任务的时间百分比。 <ul><li><strong>用户态利用率</strong>：执行应用程序代码的时间。</li><li><strong>内核态利用率</strong>：执行操作系统内核代码的时间（如系统调用、中断处理）。</li><li><strong>I/O 等待时间</strong>：CPU 空闲，但等待 I/O（通常是磁盘或网络）完成的时间。<strong>高 I/O 等待通常意味着瓶颈在 I/O，而非 CPU。</strong></li><li><strong>空闲时间</strong>：CPU 完全空闲的时间。</li></ul></li><li><strong>负载平均值</strong>：系统在特定时间间隔内（1分钟、5分钟、15分钟）的<strong>平均可运行线程数</strong>和<strong>不可中断睡眠线程数</strong>。它反映了系统的“繁忙”程度，而不仅仅是 CPU 利用率。</li><li><strong>上下文切换</strong>：CPU 从一个进程（或线程）切换到另一个的过程。频繁的上下文切换会带来开销。</li><li><strong>中断</strong>：硬件或软件发出请求，要求 CPU 暂停当前工作去处理紧急事件。</li><li><strong>时钟速度与核心数</strong>：物理硬件的基准能力。</li></ul><h3 id="_2-cpu-性能分析的整体思路" tabindex="-1">2. CPU 性能分析的整体思路 <a class="header-anchor" href="#_2-cpu-性能分析的整体思路" aria-label="Permalink to &quot;2. CPU 性能分析的整体思路&quot;">​</a></h3><p>一个高效的 CPU 性能分析流程应该遵循从宏观到微观、从现象到根源的步骤。下面的图表清晰地展示了这一过程：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">flowchart TD</span></span>
<span class="line"><span class="__shiki_140thh">    A[开始：发现系统缓慢] --&gt; B[宏观指标检查&lt;br&gt;（利用率， 负载， I/O等待）]</span></span>
<span class="line"><span class="__shiki_140thh">    B --&gt; C{高用户态利用率？}</span></span>
<span class="line"><span class="__shiki_140thh">    C -- 是 --&gt; D[分析用户空间进程]</span></span>
<span class="line"><span class="__shiki_140thh">    subgraph D [用户空间分析]</span></span>
<span class="line"><span class="__shiki_140thh">        D1[使用 \`perf\` 分析&lt;br&gt;On-CPU 热点]</span></span>
<span class="line"><span class="__shiki_140thh">        D2[使用 \`offcputime\` 分析&lt;br&gt;Off-CPU 等待]</span></span>
<span class="line"><span class="__shiki_140thh">    end</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_140thh">    C -- 否 --&gt; E{高I/O等待？}</span></span>
<span class="line"><span class="__shiki_140thh">    E -- 是 --&gt; F[分析I/O与阻塞调用]</span></span>
<span class="line"><span class="__shiki_140thh">    subgraph F [I/O/阻塞分析]</span></span>
<span class="line"><span class="__shiki_140thh">        F1[使用 \`pidstat\` 查看阻塞]</span></span>
<span class="line"><span class="__shiki_140thh">        F2[使用 \`offcputime\` 抓取堆栈]</span></span>
<span class="line"><span class="__shiki_140thh">    end</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_140thh">    C -- 否 --&gt; G{高系统态利用率？&lt;br&gt;或上下文切换/中断高？}</span></span>
<span class="line"><span class="__shiki_140thh">    G -- 是 --&gt; H[分析内核活动]</span></span>
<span class="line"><span class="__shiki_140thh">    subgraph H [内核空间分析]</span></span>
<span class="line"><span class="__shiki_140thh">        H1[使用 \`perf\` 分析&lt;br&gt;内核调用热点]</span></span>
<span class="line"><span class="__shiki_140thh">        H2[使用 \`execsnoop\` 检查&lt;br&gt;短时进程]</span></span>
<span class="line"><span class="__shiki_140thh">    end</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_140thh">    D &amp; F &amp; H --&gt; I[定位根本原因&lt;br&gt;（应用代码/配置/系统调用）]</span></span>
<span class="line"><span class="__shiki_140thh">    I --&gt; J[优化与验证]</span></span></code></pre></div><h3 id="_3-关键工具集" tabindex="-1">3. 关键工具集 <a class="header-anchor" href="#_3-关键工具集" aria-label="Permalink to &quot;3. 关键工具集&quot;">​</a></h3><p>根据上图的分析路径，我们需要使用不同的工具来获取数据。</p><h4 id="_3-1-宏观状态工具-第一眼诊断" tabindex="-1">3.1 宏观状态工具（第一眼诊断） <a class="header-anchor" href="#_3-1-宏观状态工具-第一眼诊断" aria-label="Permalink to &quot;3.1 宏观状态工具（第一眼诊断）&quot;">​</a></h4><p>这些工具用于快速获取系统的整体健康状况。</p><ul><li><p><strong><code>top</code> / <code>htop</code></strong></p><ul><li><strong>功能</strong>：实时显示进程和系统资源使用情况。</li><li><strong>关键指标</strong>： <ul><li><code>%Cpu(s)</code> 行：<code>us</code>（用户）, <code>sy</code>（系统）, <code>wa</code>（I/O等待）, <code>id</code>（空闲）。</li><li><code>LOAD AVERAGE</code>： 1, 5, 15分钟平均负载。</li></ul></li><li><strong>用法</strong>：运行 <code>top</code>，按 <code>1</code> 查看每个 CPU 核心的详情。</li></ul></li><li><p><strong><code>vmstat</code></strong></p><ul><li><strong>功能</strong>：报告关于进程、内存、分页、块 I/O、陷阱和 CPU 活动的信息。</li><li><strong>关键指标</strong>： <ul><li><code>r</code>：可运行进程数。</li><li><code>cs</code>：上下文切换次数。</li><li><code>us</code>, <code>sy</code>, <code>id</code>, <code>wa</code>：同 <code>top</code>。</li></ul></li><li><strong>用法</strong>：<code>vmstat 1</code>（每秒输出一次）。</li></ul></li><li><p><strong><code>mpstat</code></strong></p><ul><li><strong>功能</strong>：报告每个 CPU 核心的统计数据。</li><li><strong>用法</strong>：<code>mpstat -P ALL 1</code>。用于检查 CPU 使用率是否均衡，或者是否有单个核心被打满。</li></ul></li></ul><h4 id="_3-2-深入分析工具-寻找根因" tabindex="-1">3.2 深入分析工具（寻找根因） <a class="header-anchor" href="#_3-2-深入分析工具-寻找根因" aria-label="Permalink to &quot;3.2 深入分析工具（寻找根因）&quot;">​</a></h4><p>当宏观工具指出方向后，使用这些工具进行深度剖析。</p><ul><li><p><strong><code>pidstat</code></strong></p><ul><li><strong>功能</strong>：用于监控单个任务的资源使用情况。</li><li><strong>用法</strong>： <ul><li><code>pidstat -u 1</code>：查看所有进程的 CPU 使用。</li><li><code>pidstat -t -p &lt;PID&gt; 1</code>：查看指定进程及其所有线程的 CPU 使用。</li><li><code>pidstat -w -p &lt;PID&gt; 1</code>：查看指定进程的上下文切换情况（自愿/非自愿）。</li></ul></li></ul></li><li><p><strong><code>perf</code></strong></p><ul><li><strong>功能</strong>：Linux 上最强大的性能剖析工具。它可以进行 CPU 性能计数、跟踪点分析、调用栈采样等。</li><li><strong>核心用法</strong>： <ol><li><strong>采样分析</strong>：<code>perf record -F 99 -a -g -- sleep 30</code> （对全系统 <code>-a</code> 进行 99Hz 采样，持续30秒，并记录调用栈 <code>-g</code>）。</li><li><strong>报告分析</strong>：<code>perf report</code> 或 <code>perf report -n --stdio</code>。查看热点函数和调用图。</li><li><strong>统计进程</strong>：<code>perf top</code> 实时查看消耗 CPU 最多的函数。</li></ol></li><li><strong>解读火焰图</strong>： <ul><li>使用 <code>perf script</code> 输出数据，然后用 <a href="https://github.com/brendangregg/FlameGraph" target="_blank" rel="noreferrer">FlameGraph</a> 脚本生成<strong>火焰图</strong>。</li><li><strong>如何阅读</strong>：<strong>X轴显示堆栈深度</strong>，<strong>Y轴显示调用栈</strong>。每个矩形代表一个函数，宽度代表它在采样中出现的频率（即耗时）。寻找最宽的函数“平顶”就是热点。</li></ul></li></ul></li><li><p><strong>eBPF/BCC 工具集</strong></p><ul><li><strong>功能</strong>：下一代动态追踪工具，可以在内核中安全地运行小程序，以极低的开销提供强大的观测能力。</li><li><strong>关键工具</strong>： <ul><li><strong><code>cpuunclaimed</code></strong>：检查 CPU 利用率是否均衡，是否有“空闲”的 CPU 周期因为调度问题而未被使用。</li><li><strong><code>runqlat</code></strong>：测量任务在运行队列中等待被调度的时间。如果等待时间很长，说明 CPU 饱和。</li><li><strong><code>offcputime</code></strong>：追踪进程在 Off-CPU（即不在运行）状态的时间，并生成火焰图。<strong>专门用于分析阻塞和等待问题</strong>。</li><li><strong><code>execsnoop</code></strong>：追踪短命的进程。这些进程在 <code>top</code> 中很难捕捉，但可能会引起频繁的 CPU 峰值。</li></ul></li></ul></li></ul><h3 id="_4-实战场景与命令速查" tabindex="-1">4. 实战场景与命令速查 <a class="header-anchor" href="#_4-实战场景与命令速查" aria-label="Permalink to &quot;4. 实战场景与命令速查&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">怀疑点</th><th style="text-align:left;">分析命令</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>应用响应慢，CPU 用户态利用率高</strong></td><td style="text-align:left;">应用代码自身存在热点函数。</td><td style="text-align:left;">1. <code>top</code> 找到高 CPU 进程 PID。<br>2. <code>perf record -F 99 -g -p &lt;PID&gt; -- sleep 30</code><br>3. 生成火焰图，分析最宽的平顶。</td></tr><tr><td style="text-align:left;"><strong>系统整体卡顿，负载高但 CPU 利用率不高</strong></td><td style="text-align:left;">I/O 或锁竞争导致进程大量阻塞。</td><td style="text-align:left;">1. <code>vmstat 1</code> 查看 <code>wa</code> 和 <code>r</code> 队列。<br>2. <code>pidstat -w 1</code> 查看上下文切换。<br>3. <strong>使用 <code>offcputime-bpfcc</code> 生成 Off-CPU 火焰图</strong>，查看阻塞在哪些系统调用或锁上。</td></tr><tr><td style="text-align:left;"><strong>CPU 系统态利用率异常高</strong></td><td style="text-align:left;">系统调用、中断或上下文切换过于频繁。</td><td style="text-align:left;">1. <code>pidstat -w 1</code> 查看上下文切换来源。<br>2. <code>perf record -e &#39;sched:*&#39; -a -- sleep 10</code> 追踪调度事件。<br>3. <code>execsnoop-bpfcc</code> 检查是否有大量短时进程。<br>4. 使用 <code>perf</code> 采样内核空间，查看内核中的热点。</td></tr><tr><td style="text-align:left;"><strong>单个 CPU 核心 100%</strong></td><td style="text-align:left;">应用为单线程或存在“惊群效应”。</td><td style="text-align:left;">1. <code>mpstat -P ALL 1</code> 确认是哪个核心。<br>2. <code>pidstat -t -p &lt;PID&gt; 1</code> 查看该进程的哪个线程在消耗 CPU。<br>3. <code>perf top -C &lt;CPUID&gt;</code> 指定核心进行实时剖析。</td></tr><tr><td style="text-align:left;"><strong>抖动/毛刺</strong></td><td style="text-align:left;">偶发的定时任务或后台作业。</td><td style="text-align:left;">1. <code>top -d 1</code> 实时观察。<br>2. <strong><code>execsnoop-bpfcc</code> 是抓取短时进程的神器</strong>。<br>3. 使用 <code>perf record -a -g</code> 进行长时间记录，然后在毛刺发生期间和之后使用 <code>perf report --time</code> 进行时间范围分析。</td></tr></tbody></table><h3 id="_5-高级技巧与注意事项" tabindex="-1">5. 高级技巧与注意事项 <a class="header-anchor" href="#_5-高级技巧与注意事项" aria-label="Permalink to &quot;5. 高级技巧与注意事项&quot;">​</a></h3><ol><li><strong>理解 CPU 拓扑</strong>：了解物理 CPU、核心、超线程。使用 <code>lscpu</code> 查看。</li><li><strong>性能剖析的开销</strong>：<code>perf</code> 和 eBPF 工具通常开销很低（&lt;5%），但在生产环境仍需谨慎。<code>perf</code> 采样频率不宜过高。</li><li><strong>符号表</strong>：为了 <code>perf</code> 和 eBPF 工具能显示函数名而不是内存地址，需要确保应用程序和系统库都带有调试符号（<code>-g</code> 编译）。对于生产环境，可以单独安装 <code>-dbgsym</code> 包或使用 <code>perf inject</code>。</li><li><strong>容器环境</strong>：在容器内，视野受限。通常需要在宿主机上使用 <code>perf</code> 或 eBPF 工具，并通过 <code>-p</code> 指定容器内进程在宿主机上的 PID 来进行分析。</li><li><strong>火焰图是朋友</strong>： <ul><li><strong>On-CPU 火焰图</strong>：回答“CPU 时间花在哪里了？”</li><li><strong>Off-CPU 火焰图</strong>：回答“进程在等待什么？”</li><li><strong>差分火焰图</strong>：比较两个性能剖面，快速找到回归点。</li></ul></li></ol><h3 id="_6-总结" tabindex="-1">6. 总结 <a class="header-anchor" href="#_6-总结" aria-label="Permalink to &quot;6. 总结&quot;">​</a></h3><p>CPU 性能分析是一个系统性工程：</p><ol><li><strong>从不加区分的测量开始</strong>：使用 <code>top</code>, <code>vmstat</code> 获取宏观状态。</li><li><strong>提出假设</strong>：是高用户态？高系统态？还是高 I/O 等待？</li><li><strong>使用专项工具验证</strong>： <ul><li><strong>On-CPU 问题</strong> -&gt; <code>perf</code> (火焰图)</li><li><strong>Off-CPU 问题</strong> -&gt; <code>offcputime</code> (Off-CPU 火焰图)</li><li><strong>调度/切换问题</strong> -&gt; <code>pidstat -w</code>, <code>runqlat</code></li><li><strong>短时进程问题</strong> -&gt; <code>execsnoop</code></li></ul></li><li><strong>定位到代码行</strong>：通过工具输出的调用栈和火焰图，定位到消耗资源的具体函数和代码逻辑。</li><li><strong>优化并重复测试</strong>：修复问题后，重复上述流程以验证优化效果。</li></ol><p>这份笔记涵盖了从理论到实践的核心知识。熟练掌握这些概念和工具，将使你能够系统地分析和解决绝大多数 CPU 相关的性能瓶颈。</p>`,28)])])}const _=s(n,[["render",a]]);export{h as __pageData,_ as default};
